<script setup lang="ts">
import { Pause, Play, Ban, RotateCcw, Save, SlidersHorizontal } from 'lucide-vue-next'
definePageMeta({layout:'teacher'}); const config=useRuntimeConfig(); const token=useCookie<string|null>('token'); const {user}=useAuth(); const {exams,getExams}=useExams(); const examId=ref<number|null>(null); const students=ref<any[]>([]); const results=ref<any[]>([]); const classes=ref<any[]>([]); const attempts=ref<any[]>([]); const filters=reactive({class_id:'',date_from:'',date_to:'',min_score:0,max_score:10})
const headers=()=>({Authorization:`Bearer ${token.value}`,'x-user-id':String(user.value?.id),'x-user-role':String(user.value?.role)}); const api=(url:string,o:any={})=>$fetch(url,{baseURL:config.public.apiBase,headers:headers(),...o})
const loadPolicies=async()=>{if(examId.value) students.value=await api(`/exams/${examId.value}/student-policies`) as any[]}
const save=async(s:any)=>{await api(`/exams/${examId.value}/students/${s.student_id}/policy`,{method:'PUT',body:{extra_minutes:s.extra_minutes,extra_attempts:s.extra_attempts}});await loadPolicies()}
const action=async(s:any,a:string)=>{await api(`/exams/${examId.value}/students/${s.student_id}/session-action`,{method:'POST',body:{action:a}});await loadPolicies()}
const report=async()=>{const q=new URLSearchParams(); if(examId.value)q.set('exam_id',String(examId.value)); Object.entries(filters).forEach(([k,v])=>{if(v!==''&&v!=null)q.set(k,String(v))}); results.value=await api(`/reports/results-filtered?${q}`) as any[]; if(examId.value){classes.value=await api(`/reports/exams/${examId.value}/class-comparison`) as any[];attempts.value=await api(`/reports/exams/${examId.value}/attempt-comparison`) as any[]}}
onMounted(getExams); watch(examId,()=>{loadPolicies();report()})
</script><template><div class="space-y-6"><header><h2 class="text-2xl font-bold">Điều hành thi & báo cáo</h2><p class="text-slate-500">Gia hạn riêng, kiểm soát phiên thi và phân tích kết quả.</p></header><section class="surface-card p-5"><label class="text-sm font-medium">Chọn đề thi</label><select v-model="examId" class="mt-2 w-full rounded-lg border p-3"><option :value="null">-- Chọn đề --</option><option v-for="e in exams" :key="e.id" :value="e.id">{{e.title}}</option></select></section><section v-if="examId" class="surface-card overflow-hidden"><div class="p-5 border-b"><h3 class="font-bold">Chính sách theo sinh viên</h3></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Sinh viên</th><th>Phút thêm</th><th>Lần thi thêm</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="s in students" :key="s.student_id" class="border-t"><td class="p-3"><b>{{s.student_name}}</b><br><span class="text-slate-500">{{s.student_code}}</span></td><td><input v-model.number="s.extra_minutes" type="number" min="0" class="w-20 border rounded p-2"/></td><td><input v-model.number="s.extra_attempts" type="number" min="0" class="w-20 border rounded p-2"/></td><td>{{s.session_state}}</td><td class="p-2"><div class="flex flex-wrap gap-1"><button class="btn-secondary" @click="save(s)"><Save class="w-4 h-4"/></button><button class="btn-secondary" @click="action(s,'pause')"><Pause class="w-4 h-4"/></button><button class="btn-secondary" @click="action(s,'resume')"><Play class="w-4 h-4"/></button><button class="btn-secondary" @click="action(s,'cancel')"><Ban class="w-4 h-4"/></button><button class="btn-secondary" @click="action(s,'allow_retry')"><RotateCcw class="w-4 h-4"/></button></div></td></tr></tbody></table></div></section><section class="surface-card p-5"><h3 class="font-bold flex gap-2"><SlidersHorizontal class="w-5 h-5"/>Bộ lọc kết quả</h3><div class="mt-4 grid gap-3 md:grid-cols-5"><input v-model="filters.class_id" type="number" placeholder="ID lớp" class="border rounded p-2"/><input v-model="filters.date_from" type="datetime-local" class="border rounded p-2"/><input v-model="filters.date_to" type="datetime-local" class="border rounded p-2"/><input v-model.number="filters.min_score" type="number" min="0" max="10" placeholder="Điểm từ" class="border rounded p-2"/><input v-model.number="filters.max_score" type="number" min="0" max="10" placeholder="Điểm đến" class="border rounded p-2"/></div><button class="btn-primary mt-3" @click="report">Lọc báo cáo</button><div class="mt-5 overflow-x-auto"><table class="w-full text-sm"><tr class="bg-slate-50"><th class="p-2 text-left">Sinh viên</th><th>Đề thi</th><th>Điểm</th><th>Thời gian</th></tr><tr v-for="r in results" :key="r.result_id" class="border-t"><td class="p-2">{{r.student_name}}</td><td>{{r.exam_title}}</td><td class="text-center font-bold">{{r.score}}</td><td class="text-center">{{new Date(r.finished_at).toLocaleString('vi-VN')}}</td></tr></table></div></section><div class="grid gap-6 md:grid-cols-2"><section class="surface-card p-5"><h3 class="font-bold mb-3">So sánh giữa các lớp</h3><div v-for="c in classes" :key="c.class_id" class="border-b py-2 flex justify-between"><span>{{c.class_name}}</span><b>TB {{c.average}} · {{c.attempts}} lượt</b></div></section><section class="surface-card p-5"><h3 class="font-bold mb-3">So sánh các lần thi</h3><div v-for="a in attempts" :key="`${a.student_id}-${a.attempt}`" class="border-b py-2 flex justify-between"><span>{{a.student_name}} · lần {{a.attempt}}</span><b>{{a.score}} điểm</b></div></section></div></div></template>